mapper.select:
SELECT ou.id, ou.display_name AS displayName, ou.code, ou.parent_id AS parentId, ou.remark FROM whale_organization_units ou INNER JOIN whale_user_organization_units rel ON ou.id = rel.organization_unit_id WHERE rel.user_id = #{userId} AND ou.tenant_id = #{tenantId} AND ou.is_deleted = 0 AND ou.is_enabled = 1
AND ou.display_name LIKE CONCAT('%', #{query.displayName}, '%')
AND ou.code = #{query.code}
